{
  "name": "Gold Monte Carlo Simulator",
  "description": "A sophisticated financial dashboard that uses Gemini-powered search data and Monte Carlo simulations to project Gold prices for October 2026.",
  "requestFramePermissions": []
}

import { GoogleGenAI, Type } from "@google/genai";
import { MarketData } from "../types";

const API_KEY = process.env.API_KEY || "";

export const fetchGoldMarketData = async (): Promise<MarketData> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const prompt = `
    Find the following information for Gold (XAU/USD) using historical data from the LAST 6 MONTHS:
    1. Current spot price.
    2. Annualized volatility of gold based on the last 6 months of trading data.
    3. Estimated annual return (drift) based on recent trends in the last 6 months.
    4. The high and low prices for the last 6 months.

    Return the data strictly in JSON format with the following keys:
    currentPrice, sixMonthHigh, sixMonthLow, volatilityEstimate (annualized as decimal), annualReturnEstimate (annualized as decimal).
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            currentPrice: { type: Type.NUMBER },
            sixMonthHigh: { type: Type.NUMBER, description: "6-month high" },
            sixMonthLow: { type: Type.NUMBER, description: "6-month low" },
            volatilityEstimate: { type: Type.NUMBER, description: "Annualized volatility (last 6 months)" },
            annualReturnEstimate: { type: Type.NUMBER, description: "Annualized return estimate" }
          },
          required: ["currentPrice", "sixMonthHigh", "sixMonthLow", "volatilityEstimate", "annualReturnEstimate"]
        }
      },
    });

    const jsonStr = response.text.trim();
    const parsed = JSON.parse(jsonStr);

    // Extract grounding sources
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || "Market Source",
      uri: chunk.web?.uri || "#"
    })) || [];

    return {
      ...parsed,
      lastUpdated: new Date().toLocaleDateString(),
      sources
    };
  } catch (error) {
    console.error("Error fetching market data:", error);
    // Fallback data
    return {
      currentPrice: 2650,
      sixMonthHigh: 2790,
      sixMonthLow: 2300, 
      volatilityEstimate: 0.16,
      annualReturnEstimate: 0.08,
      lastUpdated: new Date().toLocaleDateString(),
      sources: []
    };
  }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  TrendingUp, 
  Info, 
  RefreshCw, 
  BarChart3, 
  AlertCircle,
  ExternalLink,
  ChevronRight,
  Target,
  History
} from 'lucide-react';
import { 
  ComposedChart, 
  Line, 
  Area,
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { fetchGoldMarketData } from './services/geminiService';
import { MarketData, ProjectionStats } from './types';
import { calculateMonteCarlo } from './utils/finance';

const TARGET_DATE = new Date('2026-10-12');
const SIMULATION_PATHS = 6000;
const VISUAL_PATH_LIMIT = 100;

/**
 * Custom Tooltip component to handle multi-column layout and prevent screen overflow
 */
const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    const medianEntry = payload.find((p: any) => p.name === 'median');
    const pathEntries = payload.filter((p: any) => p.dataKey && p.dataKey.startsWith('path_'));

    return (
      <div className="bg-[#0d0d12]/95 backdrop-blur-md border border-white/10 p-3 rounded-xl shadow-2xl min-w-[320px] max-w-[450px]">
        <div className="flex justify-between items-center mb-2 border-b border-white/5 pb-1.5">
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-wider">Forecast: Day {label}</p>
          {medianEntry && (
            <p className="text-emerald-400 text-[11px] font-bold">
              Median: ${medianEntry.value.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
            </p>
          )}
        </div>

        <div className="max-h-[280px] overflow-y-auto pr-1 scroll-smooth" style={{ scrollbarWidth: 'thin' }}>
          <div className="grid grid-cols-3 gap-x-4 gap-y-1">
            {pathEntries.map((entry: any, index: number) => (
              <div key={index} className="flex justify-between items-center border-b border-white/5 pb-0.5">
                <span className="text-slate-500 text-[8px] font-mono">#{index + 1}</span>
                <span className="text-yellow-500/90 text-[9px] font-medium font-mono">
                  ${entry.value.toFixed(0)}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }
  return null;
};

const App: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [marketData, setMarketData] = useState<MarketData | null>(null);
  const [simulationData, setSimulationData] = useState<any[]>([]);
  const [stats, setStats] = useState<ProjectionStats | null>(null);

  const tradingDays = useMemo(() => {
    const today = new Date();
    const diffTime = TARGET_DATE.getTime() - today.getTime();
    if (diffTime < 0) return 0;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return Math.floor(diffDays * (252 / 365));
  }, []);

  const runSimulation = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchGoldMarketData();
      setMarketData(data);

      const paths = calculateMonteCarlo(
        data.currentPrice,
        tradingDays,
        data.annualReturnEstimate,
        data.volatilityEstimate,
        SIMULATION_PATHS
      );

      const chartData = Array.from({ length: tradingDays + 1 }, (_, i) => {
        const pricesAtDay = paths.map(path => path[i]).sort((a, b) => a - b);
        const entry: any = { 
          day: i,
          p25: pricesAtDay[Math.floor(pricesAtDay.length * 0.25)],
          p75: pricesAtDay[Math.floor(pricesAtDay.length * 0.75)],
          median: pricesAtDay[Math.floor(pricesAtDay.length * 0.5)],
        };
        paths.slice(0, VISUAL_PATH_LIMIT).forEach((path, idx) => {
          entry[`path_${idx}`] = path[i];
        });
        return entry;
      });

      const finalPrices = paths.map(p => p[p.length - 1]).sort((a, b) => a - b);
      const median = finalPrices[Math.floor(finalPrices.length * 0.5)];
      const p5 = finalPrices[Math.floor(finalPrices.length * 0.05)];
      const p95 = finalPrices[Math.floor(finalPrices.length * 0.95)];

      setSimulationData(chartData);
      setStats({
        median,
        p5,
        p95,
        expectedReturn: ((median - data.currentPrice) / data.currentPrice) * 100
      });

    } catch (err) {
      setError("Failed to fetch market data. Please check your API configuration.");
    } finally {
      setLoading(false);
    }
  }, [tradingDays]);

  useEffect(() => {
    runSimulation();
  }, [runSimulation]);

  return (
    <div className="min-h-screen bg-[#000000] text-slate-100 p-4 md:p-8">
      {/* Header */}
      <header className="max-w-7xl mx-auto mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold bg-gradient-to-r from-yellow-400 to-amber-600 bg-clip-text text-transparent flex items-center gap-2">
            <TrendingUp className="w-8 h-8 text-yellow-500" />
            Gold Monte Carlo Simulator
          </h1>
          <p className="text-slate-400 mt-1 flex items-center gap-2">
            Target Horizon: <span className="text-yellow-500/80 font-semibold italic">October 12, 2026</span>
          </p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={runSimulation}
            disabled={loading}
            className="flex items-center justify-center gap-2 bg-[#0d0d12] hover:bg-[#1a1a24] disabled:opacity-50 transition-colors px-6 py-2.5 rounded-lg font-medium border border-white/5 shadow-lg"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            {loading ? 'Processing...' : 'Recalculate Projections'}
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto space-y-6">
        {error && (
          <div className="bg-red-500/10 border border-red-500/50 rounded-xl p-4 flex items-start gap-3 text-red-200">
            <AlertCircle className="w-5 h-5 mt-0.5 shrink-0" />
            <p>{error}</p>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          {/* Market Stats Sidebar */}
          <div className="md:col-span-1 space-y-6">
            <div className="bg-[#0d0d12] border border-white/5 rounded-2xl p-6 shadow-xl relative overflow-hidden">
              <h2 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-4 flex items-center gap-2">
                <Target className="w-4 h-4" /> 6-Month Baseline
              </h2>
              {loading ? (
                <div className="space-y-4 animate-pulse">
                  {[1, 2, 3].map(i => <div key={i} className="h-12 bg-white/5 rounded-md" />)}
                </div>
              ) : (
                <div className="space-y-5">
                  <div className="flex flex-col">
                    <span className="text-xs text-slate-500">Current Spot Price</span>
                    <span className="text-2xl font-bold text-slate-100">${marketData?.currentPrice.toLocaleString()}</span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-xs text-slate-500">Annualized Trend</span>
                    <span className={`text-lg font-medium ${marketData?.annualReturnEstimate && marketData.annualReturnEstimate > 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                      {((marketData?.annualReturnEstimate || 0) * 100).toFixed(2)}%
                    </span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-xs text-slate-500">6M Volatility (Annualized)</span>
                    <span className="text-lg font-medium text-slate-200">{((marketData?.volatilityEstimate || 0) * 100).toFixed(2)}%</span>
                  </div>
                </div>
              )}
            </div>

            <div className="bg-[#0d0d12] border border-white/5 rounded-2xl p-6 shadow-xl">
              <h2 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-4 flex items-center gap-2">
                <BarChart3 className="w-4 h-4" /> Probabilistic Forecast
              </h2>
              {loading ? (
                <div className="space-y-4 animate-pulse">
                  {[1, 2, 3].map(i => <div key={i} className="h-12 bg-white/5 rounded-md" />)}
                </div>
              ) : (
                <div className="space-y-5">
                  <div className="flex flex-col">
                    <span className="text-xs text-slate-500 italic">Oct 2026 Price (Median)</span>
                    <span className="text-2xl font-bold text-yellow-500">${stats?.median.toLocaleString(undefined, {maximumFractionDigits: 2})}</span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-xs text-slate-500">Expected Total Return</span>
                    <span className={`text-lg font-medium ${stats?.expectedReturn && stats.expectedReturn > 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                      {stats?.expectedReturn.toFixed(2)}%
                    </span>
                  </div>
                  <div className="pt-2 border-t border-white/5">
                    <span className="text-xs text-slate-500 block mb-2">Confidence Band (90%)</span>
                    <div className="flex justify-between items-end">
                      <div className="flex flex-col">
                        <span className="text-[10px] text-rose-400/70 uppercase">P5 Tail</span>
                        <span className="font-semibold text-sm">${stats?.p5.toLocaleString(undefined, {maximumFractionDigits: 0})}</span>
                      </div>
                      <div className="w-12 h-px bg-white/10 mb-2"></div>
                      <div className="flex flex-col items-end">
                        <span className="text-[10px] text-emerald-400/70 uppercase">P95 Tail</span>
                        <span className="font-semibold text-sm">${stats?.p95.toLocaleString(undefined, {maximumFractionDigits: 0})}</span>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Main Visualizer */}
          <div className="md:col-span-3 space-y-6">
            <div className="bg-[#0d0d12] border border-white/5 rounded-2xl p-6 shadow-xl h-[520px] flex flex-col">
              <div className="flex items-center justify-between mb-6">
                <div>
                  <h2 className="text-xl font-bold text-slate-100 flex items-center gap-2">
                    Simulated Price Trajectories
                  </h2>
                  <p className="text-xs text-slate-400 italic">
                    Showing <span className="text-emerald-400 font-bold">100</span> visual trajectories from an ensemble of {SIMULATION_PATHS.toLocaleString()}
                  </p>
                </div>
              </div>

              <div className="flex-1 w-full min-h-0">
