                      <History className="w-8 h-8 text-yellow-500/50 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
                    </div>
                  </div>
                ) : (
                  <ResponsiveContainer width="100%" height="100%">
                    <ComposedChart data={simulationData} margin={{ top: 10, right: 30, left: 20, bottom: 20 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#1a1a24" vertical={false} />
                      <XAxis 
                        dataKey="day" 
                        stroke="#475569" 
                        fontSize={10} 
                        tickFormatter={(val) => `D+${val}`}
                        label={{ value: 'Trading Days Remaining', position: 'insideBottom', offset: -10, fontSize: 10, fill: '#64748b' }}
                      />
                      <YAxis 
                        stroke="#475569" 
                        fontSize={10} 
                        domain={['auto', 'auto']}
                        tickFormatter={(val) => `$${val.toLocaleString()}`}
                      />
                      <Tooltip content={<CustomTooltip />} />

                      {/* Interquartile Range Area */}
                      <Area
                        type="monotone"
                        dataKey="p75"
                        baseLine={simulationData.map(d => d.p25)}
                        stroke="none"
                        fill="#10b981"
                        fillOpacity={0.15}
                        isAnimationActive={true}
                        animationDuration={1500}
                        name="Interquartile Range"
                      />

                      {/* Stochastic paths */}
                      {Array.from({ length: VISUAL_PATH_LIMIT }).map((_, i) => (
                        <Line
                          key={i}
                          type="monotone"
                          dataKey={`path_${i}`}
                          stroke="#eab308"
                          strokeOpacity={0.15}
                          strokeWidth={0.5}
                          dot={false}
                          activeDot={false}
                          isAnimationActive={true}
                          animationDuration={1000}
                        />
                      ))}

                      {/* Median path highlight */}
                      <Line
                        type="monotone"
                        dataKey="median"
                        stroke="#10b981"
                        strokeWidth={2.5}
                        dot={false}
                        activeDot={true}
                        animationDuration={2000}
                        name="median"
                      />
                    </ComposedChart>
                  </ResponsiveContainer>
                )}
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-[#0d0d12] border border-white/5 rounded-2xl p-6 shadow-xl relative overflow-hidden">
                <h3 className="text-sm font-semibold text-slate-400 uppercase mb-4 flex items-center gap-2">
                  Simulation Parameters
                </h3>
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <span className="text-slate-500 text-sm">Target Maturity</span>
                    <span className="text-slate-100 font-medium">October 12, 2026</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-slate-500 text-sm">Trajectories (N)</span>
                    <span className="text-emerald-400 font-medium">{SIMULATION_PATHS.toLocaleString()}</span>
                  </div>
                </div>
              </div>

              <div className="bg-[#0d0d12] border border-white/5 rounded-2xl p-6 shadow-xl">
                <h3 className="text-sm font-semibold text-slate-400 uppercase mb-4 flex items-center gap-2">
                  <ChevronRight className="w-4 h-4" /> Probabilistic Model
                </h3>
                <p className="text-xs text-slate-500 leading-relaxed italic">
                  Utilizing Geometric Brownian Motion (GBM) with 6-month historical drift and volatility parameters. 
                  The interquartile shaded zone indicates the statistically significant distribution density where 50% of simulated outcomes reside.
                </p>
              </div>
            </div>
          </div>
        </div>
      </main>

