        <p className="text-xs uppercase tracking-widest font-bold text-slate-500 mb-2">Institutional-Grade Stochastic Modeling</p>
        <p className="text-[10px] leading-relaxed max-w-2xl mx-auto opacity-60">
          Monte Carlo simulations are based on random walk theory and historical log-normal distributions. 
          Past performance (6-month baseline) is used to calibrate drift (μ) and diffusion (σ) for future projections.
        </p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
