            <div className="bg-[#0d0d12] border border-white/5 rounded-2xl p-6 shadow-xl relative overflow-hidden">
              <h2 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-4 flex items-center gap-2">
                <Target className="w-4 h-4" /> 6-Month Baseline
              </h2>
