/**
 * Custom Tooltip component to handle multi-column layout and prevent screen overflow
 */
const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    const medianEntry = payload.find((p: any) => p.name === 'median');
    const pathEntries = payload.filter((p: any) => p.dataKey && p.dataKey.startsWith('path_'));

    return (
      <div className="bg-[#0d0d12]/95 backdrop-blur-md border border-white/10 p-3 rounded-xl shadow-2xl min-w-[320px] max-w-[450px]">
        <div className="flex justify-between items-center mb-2 border-b border-white/5 pb-1.5">
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-wider">Forecast: Day {label}</p>
          {medianEntry && (
            <p className="text-emerald-400 text-[11px] font-bold">
              Median: ${medianEntry.value.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
            </p>
          )}
        </div>

        <div className="max-h-[280px] overflow-y-auto pr-1 scroll-smooth" style={{ scrollbarWidth: 'thin' }}>
          <div className="grid grid-cols-3 gap-x-4 gap-y-1">
            {pathEntries.map((entry: any, index: number) => (
              <div key={index} className="flex justify-between items-center border-b border-white/5 pb-0.5">
                <span className="text-slate-500 text-[8px] font-mono">#{index + 1}</span>
                <span className="text-yellow-500/90 text-[9px] font-medium font-mono">
                  ${entry.value.toFixed(0)}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }
  return null;
};

const App: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [marketData, setMarketData] = useState<MarketData | null>(null);
  const [simulationData, setSimulationData] = useState<any[]>([]);
  const [stats, setStats] = useState<ProjectionStats | null>(null);

  const tradingDays = useMemo(() => {
    const today = new Date();
    const diffTime = TARGET_DATE.getTime() - today.getTime();
    if (diffTime < 0) return 0;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return Math.floor(diffDays * (252 / 365));
  }, []);

  const runSimulation = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchGoldMarketData();
      setMarketData(data);

      const paths = calculateMonteCarlo(
        data.currentPrice,
        tradingDays,
        data.annualReturnEstimate,
        data.volatilityEstimate,
        SIMULATION_PATHS
      );

      const chartData = Array.from({ length: tradingDays + 1 }, (_, i) => {
        const pricesAtDay = paths.map(path => path[i]).sort((a, b) => a - b);
        const entry: any = { 
          day: i,
          p25: pricesAtDay[Math.floor(pricesAtDay.length * 0.25)],
          p75: pricesAtDay[Math.floor(pricesAtDay.length * 0.75)],
          median: pricesAtDay[Math.floor(pricesAtDay.length * 0.5)],
