import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  TrendingUp, 
  RefreshCw, 
  BarChart3, 
  AlertCircle,
  ExternalLink,
  ChevronRight,
  Target,
  History,
  Link as LinkIcon,
