import { GoogleGenAI, Type } from "@google/genai";
import { MarketData } from "../types";

const API_KEY = process.env.API_KEY || "";

export const fetchGoldMarketData = async (): Promise<MarketData> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const prompt = `
    Find the following information for Gold (XAU/USD) using historical data from the LAST 5 YEARS:
    1. Current spot price.
    2. Annualized volatility of gold based on the last 5 years of trading data.
    3. Estimated annual return (drift) based on the trend in the last 5 years.
    4. The high and low prices for the last 5 years.

    Return the data strictly in JSON format with the following keys:
    currentPrice, sixMonthHigh, sixMonthLow, volatilityEstimate (annualized as decimal), annualReturnEstimate (annualized as decimal).
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            currentPrice: { type: Type.NUMBER },
            sixMonthHigh: { type: Type.NUMBER, description: "5-year high price" },
            sixMonthLow: { type: Type.NUMBER, description: "5-year low price" },
            volatilityEstimate: { type: Type.NUMBER, description: "Annualized volatility (last 5 years)" },
            annualReturnEstimate: { type: Type.NUMBER, description: "Annualized return estimate (last 5 years)" }
          },
          required: ["currentPrice", "sixMonthHigh", "sixMonthLow", "volatilityEstimate", "annualReturnEstimate"]
        }
      },
    });

    const jsonStr = response.text.trim();
    const parsed = JSON.parse(jsonStr);

    // Extract grounding sources
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || "Market Source",
      uri: chunk.web?.uri || "#"
    })) || [];

    return {
      ...parsed,
      lastUpdated: new Date().toLocaleDateString(),
      sources
    };
  } catch (error) {
    console.error("Error fetching market data:", error);
    // Fallback data
    return {
      currentPrice: 2650,
      sixMonthHigh: 2790,
      sixMonthLow: 1450, 
      volatilityEstimate: 0.16,
      annualReturnEstimate: 0.10,
      lastUpdated: new Date().toLocaleDateString(),
      sources: []
    };
  }
};

