const TARGET_DATE = new Date('2026-06-25');
const SIMULATION_PATHS = 6000;
const VISUAL_PATH_LIMIT = 100;

// Animation timing constants for "Slow Observation" mode
const PATH_STAGGER_DELAY = 120;
const PATH_DRAW_DURATION = 4000;
const MEDIAN_START_DELAY = 6000;
const MEDIAN_DRAW_DURATION = 6000;

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    const medianEntry = payload.find((p: any) => p.name === 'median');
    const pathEntries = payload.filter((p: any) => p.dataKey && p.dataKey.startsWith('path_'));

    return (
      <div className="bg-[#0a0a0a]/95 backdrop-blur-xl border border-white/10 p-4 rounded-lg shadow-2xl min-w-[300px]">
        <div className="flex justify-between items-center mb-3 border-b border-white/5 pb-2">
          <p className="text-zinc-500 text-[10px] font-mono tracking-widest uppercase">T + {label} Days</p>
          {medianEntry && (
            <p className="text-green-500 text-[11px] font-mono font-bold">
              ${medianEntry.value.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
            </p>
          )}
        </div>

        <div className="max-h-[200px] overflow-y-auto pr-1 scroll-smooth" style={{ scrollbarWidth: 'thin' }}>
          <div className="grid grid-cols-2 gap-x-4 gap-y-1">
            {pathEntries.slice(0, 20).map((entry: any, index: number) => (
              <div key={index} className="flex justify-between items-center border-b border-white/5 pb-0.5">
                <span className="text-zinc-600 text-[9px] font-mono">P.{index + 1}</span>
                <span className="text-zinc-300 text-[9px] font-mono">
                  ${entry.value.toFixed(2)}
                </span>
              </div>
            ))}
          </div>
          {pathEntries.length > 20 && (
            <p className="text-[8px] text-zinc-600 mt-2 italic text-center">+ {pathEntries.length - 20} additional paths</p>
          )}
        </div>
      </div>
    );
  }
  return null;
};

const App: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [marketData, setMarketData] = useState<MarketData | null>(null);
  const [simulationData, setSimulationData] = useState<any[]>([]);
  const [stats, setStats] = useState<ProjectionStats | null>(null);
  const [chartKey, setChartKey] = useState(0);

  const tradingDays = useMemo(() => {
    const today = new Date();
    const diffTime = TARGET_DATE.getTime() - today.getTime();
    if (diffTime < 0) return 0;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return Math.floor(diffDays * (252 / 365));
  }, []);

  const handleReplayAnimation = () => {
    setChartKey(prev => prev + 1);
  };

  const runSimulation = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchGoldMarketData();
      setMarketData(data);

      const paths = calculateMonteCarlo(
        data.currentPrice,
        tradingDays,
        data.annualReturnEstimate,
        data.volatilityEstimate,
        SIMULATION_PATHS
      );

      const chartData = Array.from({ length: tradingDays + 1 }, (_, i) => {
        const pricesAtDay = paths.map(path => path[i]).sort((a, b) => a - b);
        const entry: any = { 
          day: i,
          p25: pricesAtDay[Math.floor(pricesAtDay.length * 0.25)],
          p75: pricesAtDay[Math.floor(pricesAtDay.length * 0.75)],
          median: pricesAtDay[Math.floor(pricesAtDay.length * 0.5)],
        };
        paths.slice(0, VISUAL_PATH_LIMIT).forEach((path, idx) => {
          entry[`path_${idx}`] = path[i];
        });
        return entry;
      });

      const finalPrices = paths.map(p => p[p.length - 1]).sort((a, b) => a - b);
      const median = finalPrices[Math.floor(finalPrices.length * 0.5)];
      const p5 = finalPrices[Math.floor(finalPrices.length * 0.05)];
      const p95 = finalPrices[Math.floor(finalPrices.length * 0.95)];

      setSimulationData(chartData);
      setStats({
        median,
        p5,
        p95,
        expectedReturn: ((median - data.currentPrice) / data.currentPrice) * 100
      });
      setChartKey(prev => prev + 1);

    } catch (err) {
      setError("Market data acquisition failed. System offline.");
    } finally {
      setLoading(false);
    }
  }, [tradingDays]);

  useEffect(() => {
    runSimulation();
  }, [runSimulation]);

  return (
    <div className="min-h-screen bg-[#000000] text-zinc-100 p-4 md:p-12 font-sans selection:bg-white selection:text-black">
      {/* Top Navigation / Header */}
      <header className="max-w-7xl mx-auto mb-16 flex flex-col md:flex-row md:items-end justify-between gap-6 border-b border-white/5 pb-8">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <Activity className="w-5 h-5 text-white" />
            <span className="text-[10px] font-mono tracking-[0.4em] text-zinc-400 uppercase">BLACKSIGMA CAPITAL</span>
          </div>
          <h1 className="text-4xl font-bold tracking-tight text-white flex flex-col md:flex-row md:items-baseline gap-4">
            Gold Monte Carlo <span className="text-zinc-600 font-light italic text-2xl tracking-normal">by Sarthak Pagar</span>
