import { GoogleGenAI, Type } from "@google/genai";
import { MarketData } from "../types";

const API_KEY = process.env.API_KEY || "";

export const fetchGoldMarketData = async (): Promise<MarketData> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const prompt = `
    Analyze the Gold market (XAU/USD) using historical data strictly from the LAST 5 YEARS (2020-2025). 
    Provide:
    1. Current spot price in USD.
    2. Annualized volatility (standard deviation of log returns) calculated over the full 5-year period.
    3. Annualized expected return (drift) based on the 5-year CAGR or trend.
    4. The absolute high and absolute low prices recorded within these 5 years.

    Return the data strictly in JSON format. Do not include markdown code blocks.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            currentPrice: { type: Type.NUMBER },
            sixMonthHigh: { type: Type.NUMBER, description: "5-year historical high" },
            sixMonthLow: { type: Type.NUMBER, description: "5-year historical low" },
            volatilityEstimate: { type: Type.NUMBER, description: "Annualized volatility as decimal (e.g. 0.15)" },
            annualReturnEstimate: { type: Type.NUMBER, description: "Annualized return estimate as decimal (e.g. 0.08)" }
          },
          required: ["currentPrice", "sixMonthHigh", "sixMonthLow", "volatilityEstimate", "annualReturnEstimate"]
        }
      },
    });

    const jsonStr = response.text.trim();
    const parsed = JSON.parse(jsonStr);

    // Extract grounding sources for transparency
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || "Market Intelligence Source",
      uri: chunk.web?.uri || "#"
    })) || [];

    return {
      ...parsed,
      lastUpdated: new Date().toLocaleDateString(),
      sources
    };
  } catch (error) {
    console.error("Critical: Failed to acquire 5-year market telemetry.", error);
    // Conservative fallback parameters based on long-term gold trends
    return {
      currentPrice: 2650,
      sixMonthHigh: 2790,
      sixMonthLow: 1450, 
      volatilityEstimate: 0.155,
      annualReturnEstimate: 0.092,
      lastUpdated: new Date().toLocaleDateString(),
      sources: []
    };
  }
};

